// InsightAI Dataset Analyzer - Phase 1-3
let parsed;
try { parsed = JSON.parse(query); } catch(e) { return JSON.stringify({ error: 'Invalid JSON input. Provide { "data": [...] } or a raw JSON array.' }); }
const data = Array.isArray(parsed) ? parsed : parsed.data;
if (!data || !Array.isArray(data) || data.length === 0) return JSON.stringify({ error: 'No valid data provided. Please provide a JSON array of records.' });
const columns = Object.keys(data[0]);
const rowCount = data.length;
const columnCount = columns.length;
const numericStats = {};
for (const col of columns) {
  const values = data.map(row => parseFloat(row[col])).filter(v => !isNaN(v));
  if (values.length >= rowCount * 0.2) {
    const sum = values.reduce((a, b) => a + b, 0);
    const mean = sum / values.length;
    const sorted = [...values].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    const median = sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid];
    const variance = values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;
    const q1 = sorted[Math.floor(sorted.length * 0.25)];
    const q3 = sorted[Math.floor(sorted.length * 0.75)];
    numericStats[col] = { count: values.length, missing: rowCount - values.length, missingPct: (((rowCount - values.length) / rowCount) * 100).toFixed(1) + '%', sum: Math.round(sum * 100) / 100, mean: Math.round(mean * 100) / 100, median: Math.round(median * 100) / 100, min: sorted[0], max: sorted[sorted.length - 1], stddev: Math.round(Math.sqrt(variance) * 100) / 100, q1: q1, q3: q3, iqr: Math.round((q3 - q1) * 100) / 100 };
  }
}
const categoricalStats = {};
for (const col of columns) {
  if (!numericStats[col]) {
    const freq = {};
    let missing = 0;
    data.forEach(row => { const val = row[col]; if (val === null || val === undefined || val === '') { missing++; return; } const key = String(val).trim(); freq[key] = (freq[key] || 0) + 1; });
    const sorted = Object.entries(freq).sort((a, b) => b[1] - a[1]);
    const topValues = {};
    sorted.slice(0, 10).forEach(([k, v]) => { topValues[k] = v; });
    categoricalStats[col] = { uniqueValues: Object.keys(freq).length, missing: missing, missingPct: ((missing / rowCount) * 100).toFixed(1) + '%', topValues: topValues, mostCommon: sorted.length > 0 ? sorted[0][0] : 'N/A', mostCommonCount: sorted.length > 0 ? sorted[0][1] : 0 };
  }
}
const seen = new Set(); let duplicates = 0;
data.forEach(row => { const key = JSON.stringify(row); if (seen.has(key)) duplicates++; else seen.add(key); });
const totalCells = rowCount * columnCount; let missingCells = 0;
data.forEach(row => { columns.forEach(col => { const v = row[col]; if (v === null || v === undefined || v === '') missingCells++; }); });
const missingRate = missingCells / totalCells; const duplicateRate = duplicates / rowCount;
const rawScore = (1 - missingRate * 0.7 - duplicateRate * 0.3) * 100;
const qualityScore = Math.max(0, Math.min(100, Math.round(rawScore)));
const qualityLabel = qualityScore >= 95 ? 'Excellent' : qualityScore >= 85 ? 'Good' : qualityScore >= 70 ? 'Fair' : 'Poor';
const outliers = {};
for (const col of Object.keys(numericStats)) {
  const st = numericStats[col];
  const lowerFence = st.q1 - 1.5 * st.iqr; const upperFence = st.q3 + 1.5 * st.iqr;
  const outCount = data.filter(row => { const v = parseFloat(row[col]); return !isNaN(v) && (v < lowerFence || v > upperFence); }).length;
  if (outCount > 0) outliers[col] = { count: outCount, lowerFence: Math.round(lowerFence * 100)/100, upperFence: Math.round(upperFence * 100)/100 };
}
return JSON.stringify({ overview: { rowCount, columnCount, columns, duplicateRows: duplicates, duplicatePct: (duplicateRate * 100).toFixed(1) + '%' }, dataQuality: { score: qualityScore, label: qualityLabel, missingCells, missingRate: (missingRate * 100).toFixed(2) + '%' }, numericAnalysis: numericStats, categoricalAnalysis: categoricalStats, outliers: outliers, notes: Object.keys(outliers).length > 0 ? 'Outliers detected in some numeric columns. Review before analysis.' : 'No significant outliers detected via IQR method.' }, null, 2);

// InsightAI KPI Calculator
let input;
try { input = JSON.parse(query); } catch(e) { return JSON.stringify({ error: 'Invalid JSON input.' }); }
const { operation, values, values2, period, labels } = input;
function mean(arr) { return arr.reduce((a, b) => a + b, 0) / arr.length; }
function variance(arr) { const m = mean(arr); return arr.reduce((a, b) => a + Math.pow(b - m, 2), 0) / arr.length; }
function round2(n) { return Math.round(n * 100) / 100; }
let result = { operation };
if (!values || !Array.isArray(values) || values.length === 0) return JSON.stringify({ error: 'values array is required and must not be empty.' });
const nums = values.map(Number).filter(v => !isNaN(v));
if (operation === 'sum') { result.sum = round2(nums.reduce((a, b) => a + b, 0)); }
else if (operation === 'average') { result.average = round2(mean(nums)); result.min = Math.min(...nums); result.max = Math.max(...nums); }
else if (operation === 'growth_rate') {
  if (nums.length < 2) return JSON.stringify({ error: 'Need at least 2 values for growth rate.' });
  const first = nums[0]; const last = nums[nums.length - 1];
  result.startValue = first; result.endValue = last; result.absoluteChange = round2(last - first);
  result.growthRate = first !== 0 ? round2(((last - first) / Math.abs(first)) * 100) + '%' : 'N/A (zero base)';
  if (first > 0 && last > 0 && nums.length > 1) { const cagr = (Math.pow(last / first, 1 / (nums.length - 1)) - 1) * 100; result.cagr = round2(cagr) + '%'; } else { result.cagr = 'N/A'; }
  if (labels && labels.length === nums.length) { result.periodByPeriod = nums.slice(1).map((v, i) => { const prev = nums[i]; return { from: labels[i], to: labels[i+1], change: round2(v - prev), pct: prev !== 0 ? round2(((v-prev)/Math.abs(prev))*100)+'%' : 'N/A' }; }); }
}
else if (operation === 'variance') { result.variance = round2(variance(nums)); result.stddev = round2(Math.sqrt(variance(nums))); result.coefficientOfVariation = mean(nums) !== 0 ? round2((Math.sqrt(variance(nums)) / Math.abs(mean(nums))) * 100) + '%' : 'N/A'; }
else if (operation === 'percentile') {
  const p = (typeof period === 'number') ? period : 50;
  const sorted = [...nums].sort((a, b) => a - b); const idx = (p / 100) * (sorted.length - 1); const lo = Math.floor(idx); const hi = Math.ceil(idx);
  result.percentile = p; result.value = round2(sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo));
}
else if (operation === 'correlation') {
  if (!values2 || !Array.isArray(values2) || values2.length !== nums.length) return JSON.stringify({ error: 'correlation requires two equal-length arrays: values and values2.' });
  const nums2 = values2.map(Number).filter(v => !isNaN(v)); const m1 = mean(nums); const m2 = mean(nums2);
  const cov = nums.reduce((s, v, i) => s + (v - m1) * (nums2[i] - m2), 0) / nums.length;
  const r = cov / (Math.sqrt(variance(nums)) * Math.sqrt(variance(nums2)));
  result.correlation = round2(r); result.strength = Math.abs(r) > 0.7 ? 'Strong' : Math.abs(r) > 0.4 ? 'Moderate' : 'Weak';
  result.direction = r > 0.01 ? 'Positive' : r < -0.01 ? 'Negative' : 'No correlation';
  result.interpretation = result.strength + ' ' + result.direction + ' correlation (r = ' + round2(r) + ')';
}
else if (operation === 'moving_average') {
  const w = (typeof period === 'number' && period > 0) ? period : 3; const ma = []; const maLabels = [];
  for (let i = w - 1; i < nums.length; i++) { const slice = nums.slice(i - w + 1, i + 1); ma.push(round2(mean(slice))); if (labels && labels[i]) maLabels.push(labels[i]); }
  result.movingAverage = ma; result.windowSize = w; if (maLabels.length > 0) result.labels = maLabels;
  result.trend = ma.length >= 2 ? (ma[ma.length-1] > ma[0] ? 'Upward' : ma[ma.length-1] < ma[0] ? 'Downward' : 'Flat') : 'Insufficient data';
}
else if (operation === 'profit_margin') {
  const revenue = nums; const costs = (values2 || []).map(Number).filter(v => !isNaN(v));
  if (costs.length !== revenue.length) return JSON.stringify({ error: 'profit_margin requires equal-length values (revenue) and values2 (costs).' });
  result.margins = revenue.map((r, i) => ({ label: labels ? labels[i] : 'Period ' + (i+1), revenue: r, cost: costs[i], profit: round2(r - costs[i]), margin: r !== 0 ? round2(((r - costs[i]) / r) * 100) + '%' : 'N/A' }));
  const totalRev = revenue.reduce((a,b)=>a+b,0); const totalCost = costs.reduce((a,b)=>a+b,0);
  result.totals = { totalRevenue: round2(totalRev), totalCost: round2(totalCost), totalProfit: round2(totalRev - totalCost), overallMargin: totalRev !== 0 ? round2(((totalRev - totalCost) / totalRev) * 100) + '%' : 'N/A' };
}
else { return JSON.stringify({ error: 'Unknown operation. Valid: sum, average, growth_rate, variance, percentile, correlation, moving_average, profit_margin.' }); }
return JSON.stringify(result, null, 2);

// InsightAI Phase 4 - Statistical Analysis & KPI Engine
let input;
try { input = JSON.parse(query); } catch(e) { return JSON.stringify({ error: 'Invalid JSON input.' }); }
const { data, valueColumns, dateColumn, groupByColumn } = input;
if (!data || !Array.isArray(data) || data.length === 0) return JSON.stringify({ error: 'No valid data provided.' });

const allCols = Object.keys(data[0]);
function round2(n) { return Math.round(n * 100) / 100; }
function arrMean(arr) { return arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0; }
function arrMedian(arr) { const s = [...arr].sort((a,b)=>a-b); const m = Math.floor(s.length/2); return s.length % 2 === 0 ? (s[m-1]+s[m])/2 : s[m]; }
function arrMode(arr) { const freq = {}; arr.forEach(v => { const k = round2(v); freq[k] = (freq[k]||0)+1; }); const maxC = Math.max(...Object.values(freq)); return Object.keys(freq).filter(k => freq[k] === maxC).slice(0,3).map(Number); }
function arrStd(arr) { const m = arrMean(arr); return Math.sqrt(arr.reduce((a,b)=>a+Math.pow(b-m,2),0)/arr.length); }

const numCols = (valueColumns && valueColumns.length > 0) ? valueColumns : allCols.filter(col => { const v = data.map(r=>parseFloat(r[col])).filter(v=>!isNaN(v)); return v.length >= data.length * 0.5; });
const catCols = allCols.filter(c => !numCols.includes(c));

// Descriptive Statistics
const descriptiveStats = {};
for (const col of numCols) {
  const vals = data.map(r => parseFloat(r[col])).filter(v => !isNaN(v));
  if (vals.length === 0) continue;
  const sorted = [...vals].sort((a,b)=>a-b);
  const m = arrMean(vals); const sd = arrStd(vals);
  const q1 = sorted[Math.floor(sorted.length*0.25)]; const q3 = sorted[Math.floor(sorted.length*0.75)];
  const skew = sd > 0 ? round2(vals.reduce((a,b)=>a+Math.pow((b-m)/sd,3),0)/vals.length) : 0;
  descriptiveStats[col] = { count: vals.length, sum: round2(vals.reduce((a,b)=>a+b,0)), mean: round2(m), median: round2(arrMedian(vals)), mode: arrMode(vals), min: sorted[0], max: sorted[sorted.length-1], range: round2(sorted[sorted.length-1]-sorted[0]), stddev: round2(sd), variance: round2(sd*sd), q1: q1, q3: q3, iqr: round2(q3-q1), skewness: skew, cv: m !== 0 ? round2((sd/Math.abs(m))*100)+'%' : 'N/A', distribution: skew > 1 ? 'Right-skewed' : skew < -1 ? 'Left-skewed' : 'Approximately normal' };
}

// Correlation Matrix
const corrMatrix = {};
for (const c1 of numCols) {
  corrMatrix[c1] = {};
  const v1 = data.map(r=>parseFloat(r[c1])).filter(v=>!isNaN(v));
  const m1 = arrMean(v1); const sd1 = arrStd(v1);
  for (const c2 of numCols) {
    const v2 = data.map(r=>parseFloat(r[c2])).filter(v=>!isNaN(v));
    const minLen = Math.min(v1.length, v2.length);
    if (minLen < 3 || sd1 === 0) { corrMatrix[c1][c2] = null; continue; }
    const a1 = v1.slice(0,minLen); const a2 = v2.slice(0,minLen);
    const m2 = arrMean(a2); const sd2 = arrStd(a2);
    const cov = a1.reduce((s,v,i)=>s+(v-m1)*(a2[i]-m2),0)/a1.length;
    const r = sd2 === 0 ? 0 : cov/(sd1*sd2);
    corrMatrix[c1][c2] = round2(isNaN(r)?0:r);
  }
}

// Correlation Insights
const corrInsights = [];
for (const c1 of numCols) {
  for (const c2 of numCols) {
    if (c1 >= c2) continue;
    const r = corrMatrix[c1] && corrMatrix[c1][c2];
    if (r !== null && r !== undefined && Math.abs(r) >= 0.5) {
      corrInsights.push({ columns: [c1, c2], r: r, strength: Math.abs(r) >= 0.8 ? 'Strong' : 'Moderate', direction: r > 0 ? 'Positive' : 'Negative', note: (r > 0.8 ? 'Strong positive' : r > 0.5 ? 'Moderate positive' : r < -0.8 ? 'Strong negative' : 'Moderate negative') + ' relationship between ' + c1 + ' and ' + c2 });
    }
  }
}

// Top/Bottom Performers
let topBottom = null;
if (groupByColumn && numCols.length > 0) {
  const mainCol = numCols[0];
  const grpTotals = {};
  data.forEach(row => { const grp = String(row[groupByColumn]||'Unknown'); const v = parseFloat(row[mainCol]); if (!isNaN(v)) grpTotals[grp] = (grpTotals[grp]||0)+v; });
  const sorted = Object.entries(grpTotals).sort((a,b)=>b[1]-a[1]);
  const total = sorted.reduce((s,[k,v])=>s+v,0);
  topBottom = { metric: mainCol, groupBy: groupByColumn, top5: sorted.slice(0,5).map(([k,v])=>({ name:k, value:round2(v), share:round2((v/total)*100)+'%' })), bottom5: sorted.slice(-5).reverse().map(([k,v])=>({ name:k, value:round2(v), share:round2((v/total)*100)+'%' })), totalSegments: sorted.length, grandTotal: round2(total), top3Concentration: round2((sorted.slice(0,3).reduce((s,[k,v])=>s+v,0)/total)*100)+'%' };
}

// Time-Series Analysis
let timeSeries = null;
if (dateColumn && numCols.length > 0) {
  const mainCol = numCols[0];
  const sorted2 = data.filter(r=>r[dateColumn]&&!isNaN(parseFloat(r[mainCol]))).sort((a,b)=>new Date(a[dateColumn]).getTime()-new Date(b[dateColumn]).getTime());
  if (sorted2.length >= 3) {
    const tsVals = sorted2.map(r=>parseFloat(r[mainCol]));
    const tsLabels = sorted2.map(r=>r[dateColumn]);
    const first = tsVals[0]; const last = tsVals[tsVals.length-1];
    const growthRate = first !== 0 ? round2(((last-first)/Math.abs(first))*100) : null;
    const ma3 = []; for (let i=2;i<tsVals.length;i++) ma3.push(round2((tsVals[i-2]+tsVals[i-1]+tsVals[i])/3));
    const periodChanges = tsVals.slice(1).map((v,i)=>({ from:tsLabels[i], to:tsLabels[i+1], value:round2(v), change:round2(v-tsVals[i]), changePct: tsVals[i]!==0 ? round2(((v-tsVals[i])/Math.abs(tsVals[i]))*100)+'%' : 'N/A' }));
    const peakIdx = tsVals.indexOf(Math.max(...tsVals)); const troughIdx = tsVals.indexOf(Math.min(...tsVals));
    timeSeries = { column:mainCol, dateColumn, periods:tsVals.length, firstValue:first, lastValue:last, overallGrowth: growthRate!==null ? growthRate+'%' : 'N/A', trend: last>first?'Upward':last<first?'Downward':'Flat', peakPeriod:tsLabels[peakIdx], peakValue:tsVals[peakIdx], troughPeriod:tsLabels[troughIdx], troughValue:tsVals[troughIdx], movingAverage3: ma3, periodChanges: periodChanges.slice(0,20) };
  }
}

return JSON.stringify({ phase:'Phase 4 - Statistical Analysis & KPI Engine', rowCount:data.length, descriptiveStatistics:descriptiveStats, correlationMatrix:corrMatrix, correlationInsights:corrInsights, topBottomPerformers:topBottom, timeSeriesAnalysis:timeSeries }, null, 2);

// InsightAI Phase 5 - Visualization & Dashboard Engine
let input;
try { input = JSON.parse(query); } catch(e) { return JSON.stringify({ error: 'Invalid JSON input.' }); }
const { data, chartType, title, xColumn, yColumn, topN } = input;
if (!data || !Array.isArray(data) || data.length === 0) return JSON.stringify({ error: 'No valid data provided.' });

const cols = Object.keys(data[0]);
const resolvedTitle = title || 'Business Intelligence Dashboard';
const limit = Math.min(topN || 15, data.length);
function round2(n) { return Math.round(n * 100) / 100; }

const numCols = cols.filter(col => { const v = data.map(r=>parseFloat(r[col])).filter(v=>!isNaN(v)); return v.length >= data.length * 0.5; });
const catCols = cols.filter(c => !numCols.includes(c));
const resolvedChartType = chartType || (catCols.length > 0 && numCols.length > 0 ? 'bar' : 'line');
const resolvedX = xColumn || catCols[0] || cols[0];
const resolvedY = yColumn || numCols[0] || cols[1] || cols[0];

function aggregateBy(rows, xCol, yCol, lim) {
  const groups = {};
  rows.forEach(r => { const k = String(r[xCol]||'N/A'); const v = parseFloat(r[yCol]); if (!isNaN(v)) groups[k] = (groups[k]||0)+v; });
  const sorted = Object.entries(groups).sort((a,b)=>b[1]-a[1]).slice(0, lim);
  return { labels: sorted.map(e=>e[0]), values: sorted.map(e=>round2(e[1])) };
}

const agg = aggregateBy(data, resolvedX, resolvedY, limit);
const palette = ['rgba(99,179,237,0.85)','rgba(72,187,120,0.85)','rgba(252,129,74,0.85)','rgba(159,122,234,0.85)','rgba(246,173,85,0.85)','rgba(247,98,108,0.85)','rgba(56,178,172,0.85)','rgba(237,100,166,0.85)','rgba(104,211,145,0.85)','rgba(183,148,246,0.85)','rgba(251,191,36,0.85)','rgba(249,115,22,0.85)','rgba(16,185,129,0.85)','rgba(139,92,246,0.85)','rgba(236,72,153,0.85)'];
const isLine = resolvedChartType === 'line' || resolvedChartType === 'area';
const isDoughnut = resolvedChartType === 'doughnut' || resolvedChartType === 'donut' || resolvedChartType === 'pie';
const chartjsType = resolvedChartType === 'donut' ? 'doughnut' : resolvedChartType === 'area' ? 'line' : resolvedChartType === 'horizontalBar' ? 'bar' : resolvedChartType;

const chartCfg = { type: chartjsType, data: { labels: agg.labels, datasets: [{ label: resolvedY, data: agg.values, backgroundColor: isLine ? 'rgba(99,179,237,0.15)' : agg.labels.map((_,i)=>palette[i%palette.length]), borderColor: isLine ? 'rgba(99,179,237,1)' : agg.labels.map((_,i)=>palette[i%palette.length].replace('0.85','1')), borderWidth: isLine ? 2.5 : 1.5, fill: resolvedChartType === 'area', tension: 0.4, pointRadius: isLine ? 4 : 0 }] }, options: { indexAxis: resolvedChartType === 'horizontalBar' ? 'y' : 'x', responsive: true, plugins: { legend: { position: 'bottom', labels: { color: '#e2e8f0', font: { size: 12 } } }, title: { display: true, text: resolvedTitle, color: '#f1f5f9', font: { size: 18, weight: 'bold' } } }, scales: isDoughnut ? {} : { x: { ticks: { color: '#94a3b8' }, grid: { color: 'rgba(148,163,184,0.1)' } }, y: { beginAtZero: true, ticks: { color: '#94a3b8' }, grid: { color: 'rgba(148,163,184,0.1)' } } } } };

const totalVal = round2(agg.values.reduce((a,b)=>a+b,0));
const avgVal = agg.values.length > 0 ? round2(totalVal/agg.values.length) : 0;
const maxVal = agg.values.length > 0 ? Math.max(...agg.values) : 0;
const topLabel = agg.labels[agg.values.indexOf(maxVal)] || 'N/A';
const cfgStr = JSON.stringify(chartCfg);

// Build HTML
var h = '<!DOCTYPE html>';
h += '<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>' + resolvedTitle + '</title>';
h += '<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"><' + '/script>';
h += '<style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#0f172a;color:#e2e8f0;padding:24px}.wrap{max-width:1100px;margin:0 auto}.hdr{margin-bottom:24px}.hdr h1{font-size:26px;color:#f1f5f9;font-weight:700}.hdr p{color:#64748b;font-size:13px;margin-top:4px}.kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin-bottom:24px}.kpi{background:#1e293b;border-radius:10px;padding:18px 20px;border-top:3px solid #3b82f6}.kpi.green{border-top-color:#22c55e}.kpi.orange{border-top-color:#f59e0b}.kpi.purple{border-top-color:#a855f7}.kpi-lbl{font-size:11px;color:#64748b;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px}.kpi-val{font-size:26px;font-weight:700;color:#7dd3fc}.chart-card{background:#1e293b;border-radius:12px;padding:24px}.chart-wrap{position:relative;height:420px}.footer{text-align:center;color:#334155;font-size:11px;margin-top:20px}</style>';
h += '</head><body><div class="wrap">';
h += '<div class="hdr"><h1>' + resolvedTitle + '</h1><p>InsightAI Enterprise · AI Business Intelligence Platform · Phase 5: Visualization Engine</p></div>';
h += '<div class="kpi-grid">';
h += '<div class="kpi"><div class="kpi-lbl">Total ' + resolvedY + '</div><div class="kpi-val">' + totalVal.toLocaleString() + '</div></div>';
h += '<div class="kpi green"><div class="kpi-lbl">Average</div><div class="kpi-val">' + avgVal.toLocaleString() + '</div></div>';
h += '<div class="kpi orange"><div class="kpi-lbl">Top Performer</div><div class="kpi-val">' + topLabel + '</div></div>';
h += '<div class="kpi purple"><div class="kpi-lbl">Data Points</div><div class="kpi-val">' + agg.labels.length + '</div></div>';
h += '</div>';
