h += '</div>';
h += '<script>new Chart(document.getElementById("chart").getContext("2d"),' + cfgStr + ');<' + '/script>';
h += '</body></html>';

const recs = [];
if (catCols.length > 0 && numCols.length > 0) { recs.push({type:'bar',use:'Compare values across categories'}); recs.push({type:'pie',use:'Show % share/distribution'}); recs.push({type:'doughnut',use:'Elegant distribution with center metric'}); recs.push({type:'horizontalBar',use:'Long category labels or rankings'}); }
if (numCols.length >= 2) recs.push({type:'scatter',use:'Correlation between two numeric variables'});
if (data.length > 5) { recs.push({type:'line',use:'Trend over time'}); recs.push({type:'area',use:'Cumulative trend'}); }

return JSON.stringify({ phase:'Phase 5 - Visualization & Dashboard Engine', chartGenerated:resolvedChartType, title:resolvedTitle, dataPoints:agg.labels.length, kpiSummary:{ metric:resolvedY, groupBy:resolvedX, total:totalVal, average:avgVal, maximum:maxVal, topPerformer:topLabel }, chartjsConfig:chartCfg, chartRecommendations:recs, htmlDashboard:h, instructions:'Save htmlDashboard as a .html file and open in any browser to view the interactive dashboard.' }, null, 2);

// InsightAI Phase 6 - Business Intelligence Engine
let input;
try { input = JSON.parse(query); } catch(e) { return JSON.stringify({ error: 'Invalid JSON input.' }); }
